#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up a leaderboard repository, once, for its owner: everything README's "One-time setup" lists, done with the
# GitHub CLI instead of by hand in Settings. Run it from a clone of the leaderboard repository:
#   grader/setup-leaderboard.sh
# Each step checks first and skips what is already done, so running it again is safe. Needs: gh, logged in as the
# repository's owner (or an admin), and ssh-keygen.

repo_api() { gh api "repos/$REPO$1" "${@:2}"; }

has_secret() { gh secret list -R "$REPO" --json name -q '.[].name' 2>/dev/null | grep -qx "$1"; }

run_wizard() {

TOTAL_STAGES=8

banner "Set up the leaderboard"

stage "The repository"
if ! command -v gh >/dev/null 2>&1; then warn "Install the GitHub CLI (https://cli.github.com) and run this again."; exit 1; fi
until gh auth status >/dev/null 2>&1; do
  step "Log in: in another terminal run  gh auth login"
  pause "Press Enter once you are logged in"
done
REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)
if [[ -z $REPO ]] || ! confirm "Set up $REPO (the repository this folder is a clone of)?"; then
  ask REPO "Leaderboard repository (owner/name):"
fi
until [[ "$(repo_api '' --jq .permissions.admin 2>/dev/null)" == true ]]; do
  warn "You need to be an admin of $REPO (its owner, usually)."
  ask REPO "Leaderboard repository (owner/name):"
done
printf '  %s✓ admin of%s %s\n' "$GREEN" "$RESET" "$REPO"
pause

stage "A deploy key, so only the workflows save changes"
say "The facilitator forms and the grader push their changes with a deploy key, so main can require a pull request"
say "from everyone else. This makes the key, gives the public half to $REPO and the private half to its secrets."
if has_secret LEADERBOARD_DEPLOY_KEY; then
  printf '  %s✓ already set:%s secret LEADERBOARD_DEPLOY_KEY\n' "$GREEN" "$RESET"
elif confirm "Create the deploy key now?"; then
  keydir=$(mktemp -d)
  ssh-keygen -q -t ed25519 -N "" -C leaderboard-bot -f "$keydir/leaderboard-bot"
  gh repo deploy-key add "$keydir/leaderboard-bot.pub" -R "$REPO" --allow-write --title leaderboard-bot >/dev/null
  gh secret set LEADERBOARD_DEPLOY_KEY -R "$REPO" < "$keydir/leaderboard-bot" >/dev/null
  rm -rf "$keydir"  # the private key now lives only in the repository's secrets
  WRITTEN_SECRET+=("LEADERBOARD_DEPLOY_KEY")
  printf '  %s✓ deploy key added and secret set%s (the key files are deleted)\n' "$GREEN" "$RESET"
else
  SKIPPED+=("the deploy key (README: One-time setup, step 2)")
fi
pause

stage "Protect main"
say "Nobody pushes to main directly: changes come through a pull request whose tests pass, and the deploy key may"
say "skip that, so the forms and the grader can still save."
if repo_api /rulesets --jq '.[].name' 2>/dev/null | grep -qx 'Protect main'; then
  printf '  %s✓ already there:%s ruleset "Protect main"\n' "$GREEN" "$RESET"
elif confirm "Create the \"Protect main\" ruleset now?"; then
  repo_api /rulesets -X POST --input - >/dev/null <<'JSON'
{"name": "Protect main", "target": "branch", "enforcement": "active",
 "conditions": {"ref_name": {"include": ["~DEFAULT_BRANCH"], "exclude": []}},
 "bypass_actors": [{"actor_type": "DeployKey", "bypass_mode": "always"}],
 "rules": [{"type": "deletion"}, {"type": "non_fast_forward"},
   {"type": "pull_request", "parameters": {"required_approving_review_count": 0, "dismiss_stale_reviews_on_push": false,
     "require_code_owner_review": false, "require_last_push_approval": false, "required_review_thread_resolution": false}},
   {"type": "required_status_checks", "parameters": {"strict_required_status_checks_policy": false,
     "required_status_checks": [{"context": "fast"}, {"context": "slow"}]}}]}
JSON
  printf '  %s✓ ruleset "Protect main" created%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("the \"Protect main\" ruleset (README: One-time setup, step 2.4)")
fi
pause

stage "Publish the page"
if [[ "$(repo_api /pages --jq .build_type 2>/dev/null)" == workflow ]]; then
  printf '  %s✓ already on:%s Pages, built by GitHub Actions\n' "$GREEN" "$RESET"
elif confirm "Turn on GitHub Pages, published by the \"Publish the page\" workflow?"; then
  repo_api /pages -X POST -f build_type=workflow >/dev/null 2>&1 || repo_api /pages -X PUT -f build_type=workflow >/dev/null
  printf '  %s✓ Pages on%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("GitHub Pages (Settings → Pages → Source: GitHub Actions)")
fi
pause

stage "Workflows run for collaborators only"
say "The token every workflow gets can only read, and a pull request from outside the Collaborators list waits"
say "for a collaborator to approve its run."
repo_api /actions/permissions/workflow -X PUT -f default_workflow_permissions=read -F can_approve_pull_request_reviews=false >/dev/null
repo_api /actions/permissions/fork-pr-contributor-approval -X PUT -f approval_policy=all_external_contributors >/dev/null
printf '  %s✓ read-only workflow token; outside contributors need approval%s\n' "$GREEN" "$RESET"
if gh label list -R "$REPO" --search facilitator --json name -q '.[].name' | grep -qx facilitator; then
  printf '  %s✓ already there:%s label "facilitator"\n' "$GREEN" "$RESET"
else
  gh label create facilitator -R "$REPO" --color 3A4BC0 --description "A change sent from the facilitator page" >/dev/null
  printf '  %s✓ label "facilitator" created%s (issues from the facilitator page get it)\n' "$GREEN" "$RESET"
fi
pause

stage "Facilitators"
say "Facilitators are the repository's collaborators with write access: only they can change the leaderboard."
note "Already: $(repo_api /collaborators --jq '[.[] | select(.permissions.push) | .login] | join(", ")' 2>/dev/null)"
ask FACILITATORS "GitHub usernames to invite, separated by spaces (Enter for none):" || FACILITATORS=""
for who in $FACILITATORS; do
  who=${who#@}
  if repo_api "/collaborators/$who" -X PUT -f permission=push >/dev/null 2>&1; then
    printf '  %s✓ invited%s @%s (they accept by email or at github.com/%s/invitations)\n' "$GREEN" "$RESET" "$who" "$REPO"
  else
    warn "Could not invite @$who. Check the username."
    SKIPPED+=("invite @$who (Settings → Collaborators)")
  fi
done
pause

stage "Grade what is there already"
say "The first run builds every existing submission (20 to 40 minutes); after that only new commits are graded."
if confirm "Start Grade submissions now?"; then
  gh workflow run grade.yml -R "$REPO" >/dev/null
  open_url "https://github.com/$REPO/actions/workflows/grade.yml"
else
  SKIPPED+=("the first grading run (Actions → Grade submissions → Run workflow)")
fi
pause

stage "Optional: grade each pull request as it happens"
say "Pull requests are graded once a day, and whenever a facilitator presses Grade now: nothing more is needed."
say "If you own the exercise repositories, each can also tell the leaderboard when a pull request changes, so it"
say "is graded in a minute. That needs a token you make, renewed when it expires, and a small workflow in each."
if confirm "Connect the exercise repositories now (grader/setup-pr-trigger.sh)? Most people skip this."; then
  LEADERBOARD_REPO=$REPO bash grader/setup-pr-trigger.sh
else
  :  # optional: grading still runs daily and on Grade now
fi

finish
}

run_wizard "$@"; exit
